#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

# ── Author-level helpers (findings capture) ───────────────────────────────
# This wizard's main product is a findings document, not credentials. Every
# observation is appended to $FINDINGS as it is made, so Ctrl-C mid-run never
# loses what you already saw. Secrets go to $ENV_FILE only — the ticket is
# explicit that no credential may be pasted into any ticket or findings file.

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
ENV_FILE="${ENV_FILE:-$REPO_ROOT/.env}"
FINDINGS="${FINDINGS:-$REPO_ROOT/.scratch/tender-tracker-mvp/research/06-wecom-console.md}"
SHOTS_DIR="$REPO_ROOT/.scratch/tender-tracker-mvp/research"

WEBHOOK_BASE="https://qyapi.weixin.qq.com/cgi-bin/webhook/send"
QYAPI="https://qyapi.weixin.qq.com/cgi-bin"

# record "text" — append a line to the findings file.
record() { printf '%s\n' "$1" >> "$FINDINGS"; }

# record_kv "Label" "value" — a findings bullet, with a placeholder when blank.
record_kv() { record "- **$1:** ${2:-_(not recorded)_}"; }

# record_label "Label:" — a label line, blank-separated so it never gets
# swallowed into the preceding bullet list as a lazy continuation.
record_label() { record ""; record "$1"; }

# record_fenced "lang" "text" — append a fenced block, trimming the trailing
# newline ask_block accumulates so the fence has no stray blank last line.
record_fenced() { record '```'"$1"; printf '%s\n' "${2%$'\n'}" >> "$FINDINGS"; record '```'; record ""; }

# ask_note KEY "Prompt" — single-line answer. Unlike ask(), never consults
# .env: findings are not credentials and must not be defaulted from one.
ask_note() {
  local key="$1" prompt="$2" input
  printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  read -r input || true
  printf -v "$key" '%s' "$input"
}

# ask_block KEY "Prompt" — multi-line verbatim capture, for transcribing
# console text exactly as the ticket demands. Terminated by a lone dot.
ask_block() {
  local key="$1" prompt="$2" line acc=""
  printf '  %s%s%s\n' "$BOLD" "$prompt" "$RESET"
  note "  paste as many lines as you like, then a single . on its own line"
  while IFS= read -r line; do
    [[ "$line" == "." ]] && break
    acc="$acc$line
"
  done
  printf -v "$key" '%s' "$acc"
}

# ask_choice KEY "Prompt" opt1 opt2 … — pick one; KEY gets the option text.
ask_choice() {
  local key="$1" prompt="$2"; shift 2
  local input i opt
  printf '  %s%s%s\n' "$BOLD" "$prompt" "$RESET"
  i=1; for opt in "$@"; do printf '    %s%s)%s %s\n' "$BLUE" "$i" "$RESET" "$opt"; i=$((i + 1)); done
  while :; do
    printf '  %sChoose 1-%s:%s ' "$BOLD" "$#" "$RESET"
    read -r input || true
    if [[ "$input" =~ ^[0-9]+$ ]] && [ "$input" -ge 1 ] && [ "$input" -le "$#" ]; then
      eval "printf -v \"\$key\" '%s' \"\${$input}\""
      return 0
    fi
    warn "enter a number between 1 and $#"
  done
}

# robot_send JSON — POST to the group robot. Never echoes the webhook URL
# (the key in it is the credential). Prints and returns the response body.
robot_send() {
  curl -sS -X POST -H 'Content-Type: application/json' \
    -d "$1" "$WEBHOOK_BASE?key=$ROBOT_KEY" 2>&1 || true
}

# ── Preflight ─────────────────────────────────────────────────────────────
# Refuse to run without a terminal. Every prompt would read EOF, and the two
# validating loops (webhook URL, ask_choice) would spin forever on the empty
# value they can never accept. Run this from your own shell, not an agent.
if [[ ! -t 0 ]]; then
  printf 'This wizard is interactive — run it from a terminal, not a pipe.\n' >&2
  exit 1
fi
for _bin in curl jq; do
  command -v "$_bin" >/dev/null 2>&1 || { printf 'This wizard needs %s on PATH.\n' "$_bin" >&2; exit 1; }
done
mkdir -p "$(dirname "$FINDINGS")"
if [[ ! -f "$FINDINGS" ]]; then
  record "# 06 — WeCom console: observed facts"
  record ""
  record "Console findings for ticket \`issues/06-register-wecom-app-and-robot.md\`."
  record "Written by \`wizard-06-wecom.sh\`. **No credentials in this file** — those live in"
  record "\`.env\` at the repo root (gitignored). Tickets 07 and 12 read this."
  record ""
fi
record "---"
record ""
record "## Session $(date '+%Y-%m-%d %H:%M %Z')"
record ""

banner "WeCom console — ticket 06"

# ── Stage 1 — the group robot ─────────────────────────────────────────────
stage "Group robot — create it and capture the webhook"
say "Ticket 06's most load-bearing claim is the group robot. It needs no trusted"
say "domain, no ICP filing and no IP whitelist, so this stage should succeed even"
say "if every later stage hits a wall. We do it first for exactly that reason."
printf '\n'
warn "Use a THROWAWAY test group, not the real team group — stage 5 bursts ~25 messages."
step "Open the WeCom desktop or mobile client (NOT the admin console — group"
step "  robots are created from the chat, not from work.weixin.qq.com)."
step "Create a group: include yourself and, if you can, one colleague."
step "In the group: ⋯ / 群设置 → 群机器人 (Group Robots) → 添加机器人 (Add)."
step "Name it something like 'tender-tracker-test', then copy its Webhook URL."
note "Reference: https://developer.work.weixin.qq.com/document/path/91770"
open_url "https://developer.work.weixin.qq.com/document/path/91770"
printf '\n'
while :; do
  ask_secret WECOM_ROBOT_WEBHOOK "Paste the robot Webhook URL (hidden):"
  case "$WECOM_ROBOT_WEBHOOK" in
    "$WEBHOOK_BASE?key="*) break ;;
    *) warn "that doesn't look right — it should start ${WEBHOOK_BASE}?key=" ;;
  esac
done
ROBOT_KEY="${WECOM_ROBOT_WEBHOOK#*key=}"
write_env WECOM_ROBOT_WEBHOOK "$WECOM_ROBOT_WEBHOOK"
ask_note GROUP_DESC "How many people are in this group (including you)?"
record "### 1. Group robot"
record_kv "Robot created" "yes"
record_kv "Group size" "$GROUP_DESC"
record_kv "Webhook stored in" "\`.env\` → \`WECOM_ROBOT_WEBHOOK\` (repo root, gitignored)"
record ""
pause "Robot created. Press Enter to test the mention."

# ── Stage 2 — the @mention that carries the product ───────────────────────
stage "Mention test A — @mention yourself"
say "Ticket 08's entire notification design rests on mentioned_mobile_list."
say "It has never been tested against a real group. This is that test."
printf '\n'
warn "USE E.164 WITH A LEADING + — e.g. +66933555055. Established 2026-08-12:"
warn "that format notifies; '66…', '0…' and the bare national number are all"
warn "silently ACCEPTED (errcode 0), delivered, and never bind the mention."
warn "'@all' does not notify either. There is no error for a wrong format."
printf '\n'
ask_note MY_MOBILE "Your mobile number (digits only):"
PAYLOAD_A=$(jq -nc --arg m "$MY_MOBILE" \
  '{msgtype:"text",text:{content:"[06] mention test A — this should notify you.",mentioned_mobile_list:[$m]}}')
say "Sending…"
RESP_A=$(robot_send "$PAYLOAD_A")
printf '\n'; say "Response: $RESP_A"; printf '\n'
warn "Now LOOK AT YOUR PHONE. The question is not whether the text says '@you'."
warn "It is whether WeCom gave you an actual mention notification."
ask_choice MENTION_A "What actually happened?" \
  "Real @mention — highlighted, and I got a notification" \
  "Message arrived, but the mention is plain text with no notification" \
  "Message arrived with no mention rendering at all" \
  "Nothing arrived / the call errored"
record "### 2. Mention test A — self"
record_kv "Number format used" "\`$MY_MOBILE\`"
record_kv "Observed result" "$MENTION_A"
record_label "Payload that was sent:"
record_fenced json "$PAYLOAD_A"
record_label "Response:"
record_fenced json "$RESP_A"
case "$MENTION_A" in
  "Real @mention"*) say "Good — ticket 08's design holds." ;;
  *) warn "Retry with a different number format before concluding. If no format"
     warn "produces a real mention, ticket 08 must be REOPENED: targeted reminders,"
     warn "the nag rule and per-Assignee notifications all collapse to broadcast." ;;
esac
pause "Press Enter to continue."

# ── Stage 3 — a number that is not in the group ───────────────────────────
stage "Mention test B — a number NOT in the group"
say "The notification code will sometimes mention someone who has left the group."
say "If that errors rather than being ignored, the design needs a guard."
printf '\n'
note "Default is an unassigned-looking number so no real person gets pinged."
ask_note OTHER_MOBILE "Number NOT in the group [Enter for 13800000000]:"
[[ -z "$OTHER_MOBILE" ]] && OTHER_MOBILE="13800000000"
PAYLOAD_B=$(jq -nc --arg m "$OTHER_MOBILE" \
