RESP_B=$(robot_send "$PAYLOAD_B")
printf '\n'; say "Response: $RESP_B"; printf '\n'
ask_choice MENTION_B "What happened?" \
  "Message delivered, unknown number silently ignored (expected)" \
  "Message delivered but errcode was non-zero" \
  "Message rejected outright" \
  "Something else"
record "### 3. Mention test B — non-member number"
record_kv "Number tried" "\`$OTHER_MOBILE\`"
record_kv "Observed result" "$MENTION_B"
record_label "Response:"
record_fenced json "$RESP_B"
[[ "$MENTION_B" == "Message delivered, unknown"* ]] || \
