pause "Press Enter to continue."

# ── Stage 4 — does it render for someone else ─────────────────────────────
stage "Mention test C — a second person"
say "A mention that only works for the sender is not a notification system."
printf '\n'
if confirm "Is a colleague in the group and able to check their phone now?"; then
