  record "### 4. Mention test C — second person"
  record_kv "Observed result" "SKIPPED — no second person available"
  warn "Skipped. Ticket 06 is not fully resolved until this is done."
fi
record ""
pause "Press Enter to continue."

# ── Stage 5 — rate limit ──────────────────────────────────────────────────
stage "Rate limit — 20 messages/minute per webhook"
say "The Digest and reminder batching in ticket 08 are designed around this number."
say "Docs say 20/min per webhook; nobody has confirmed what exceeding it does."
printf '\n'
warn "This sends ~25 messages in a burst. Only do it in the throwaway test group."
printf '\n'
if confirm "Run the burst now?"; then
  RATE_FIRST_FAIL=""; RATE_FAIL_BODY=""
  i=1
  while [ "$i" -le 25 ]; do
    _p=$(jq -nc --arg n "$i" '{msgtype:"text",text:{content:("[06] rate probe " + $n + "/25")}}')
    _r=$(robot_send "$_p")
    _code=$(printf '%s' "$_r" | jq -r '.errcode // "unparseable"' 2>/dev/null || echo unparseable)
    printf '  %s/25 → errcode %s\n' "$i" "$_code"
    if [[ "$_code" != "0" && -z "$RATE_FIRST_FAIL" ]]; then
      RATE_FIRST_FAIL="$i"; RATE_FAIL_BODY="$_r"
    fi
    i=$((i + 1))
  done
  printf '\n'
  record "### 5. Rate limit"
  if [[ -n "$RATE_FIRST_FAIL" ]]; then
    say "First non-zero errcode at message $RATE_FIRST_FAIL of 25."
    record_kv "First rejection" "message $RATE_FIRST_FAIL of 25"
    record "Rejection body:"
    record_fenced json "$RATE_FAIL_BODY"
  else
    say "All 25 accepted — the limit was not hit in a single burst."
    record_kv "First rejection" "none — all 25 accepted in one burst"
  fi
  step "Check the group: did all the accepted messages actually arrive?"
  ask_note RATE_DELIVERED "How many of the 25 landed in the group?"
  record_kv "Actually delivered" "$RATE_DELIVERED of 25"
else
  SKIPPED+=("Rate-limit burst probe")
  record "### 5. Rate limit"
  record_kv "Observed" "SKIPPED — docs claim 20/min, unverified"
fi
record ""
say "The robot half of ticket 06 is now done. Everything below may hit a wall —"
