# ── Stage 8 — the trusted domain attempt ──────────────────────────────────
stage "可信域名 — the test that decides ticket 07"
say "Neither research ticket could settle this from documentation: WeCom publishes"
say "no policy covering orgs registered under a non-mainland entity. You are the"
say "admin. Five minutes here beats another week of reading."
printf '\n'
step "On the app's page: Developer Interface → Web Authorization and JS-SDK"
step "  → Trusted Domain  (开发者接口 → 网页授权及JS-SDK → 设置可信域名)."
warn "There are TWO fields. Use the OAuth one — it gates redirect_uri. The JS-SDK"
warn "field is for in-client JS APIs and has nothing to do with login."
warn "Use a domain Taihue CONTROLS. A domain that does not resolve fails the"
warn "ownership (归属) check and never reaches the 备案/ICP question — which is"
warn "the only thing this stage exists to answer."
step "Try to add a domain. Use one Taihue actually owns, if any; otherwise use"
step "  the domain you intend to ship on."
step "SCREENSHOT whatever happens — success, error, or a greyed-out control."
note "WeCom's own rules page: https://open.work.weixin.qq.com/help2/pc/21316"
open_url "https://open.work.weixin.qq.com/help2/pc/21316"
printf '\n'
ask_note TRUSTED_DOMAIN "Which domain did you try?"
ask_choice DOMAIN_OUTCOME "What happened?" \
  "Blocked on org verification (需已验证/认证企业才可操作)" \
  "Rejected on 备案/主体 grounds (域名主体校验未通过 or an MIIT filing demand)" \
  "ACCEPTED — the domain was saved" \
  "Something else / the control was not there at all"
ask_block DOMAIN_TEXT "Transcribe the exact message the console gave (verbatim, Chinese as shown):"
say "Save your screenshot to: $SHOTS_DIR/"
ask_note DOMAIN_SHOT "Screenshot filename (e.g. 06-trusted-domain.png), or blank:"
record "### 8. 可信域名 attempt — DECISIVE FOR TICKET 07"
record_kv "Domain tried" "\`$TRUSTED_DOMAIN\`"
record_kv "Outcome" "$DOMAIN_OUTCOME"
[[ -n "$DOMAIN_SHOT" ]] && record_kv "Screenshot" "\`$DOMAIN_SHOT\`"
record_label "Verbatim console text:"
record_fenced "" "$DOMAIN_TEXT"
printf '\n'
case "$DOMAIN_OUTCOME" in
  Blocked*)  warn "Verification is the prerequisite. Establish 已验证/认证 first, then re-run."
             record "**Reading:** verification is a hard prerequisite; retry after 已验证/认证." ;;
  Rejected*) warn "This confirms the catch-22 from ticket 03: ICP filing needs a mainland"
             warn "entity AND mainland-hosted servers, so an ICP-filed 可信域名 and Vercel are"
             warn "mutually exclusive. WeCom web-OAuth login is DEAD for v1. Ticket 07 should"
             warn "choose email/password and key identity on wecom_userid later."
             record "**Reading:** confirms the ICP catch-22 (research/03-hosting.md §3.4). WeCom web-OAuth login is dead for v1; ticket 07 should take email/password." ;;
  ACCEPTED*) warn "This contradicts every document we have. Overseas-entity orgs may be"
             warn "treated differently than the docs imply. Record it carefully — it REOPENS"
             warn "WeCom login as genuinely viable and ticket 07 must weigh it."
             record "**Reading:** contradicts research/02 and /03. No documentation states this. Reopens WeCom login as viable — ticket 07 must reconsider." ;;
  *)         record "**Reading:** inconclusive — see verbatim text above." ;;
esac
record ""
printf '\n'
step "While you are here, note the form's constraints: how many OAuth2 callback"
step "  domains does it allow? Does it demand a WW_verify_*.txt file at the root?"
ask_block DOMAIN_FORM "Anything the form demanded or limited (blank + . to skip):"
record_label "Form constraints observed:"
record_fenced "" "$DOMAIN_FORM"
pause "Press Enter to continue."

# ── Stage 9 — trusted IP ──────────────────────────────────────────────────
stage "企业可信IP (Trusted Enterprise IP) — is the whitelist enforced?"
say "Ticket 03 found the policy: apps created after 2022-06-20 20:00 must whitelist"
say "calling IPs. This decides whether Vercel serverless can host WeCom-facing code."
printf '\n'
warn "gettoken alone is NOT a valid test — it is EXEMPT from the whitelist and"
warn "returns errcode 0 even when every business API is blocked. Observed"
warn "2026-08-12. Ticket 06's own step 3 proposed that misleading test."
say "So we get a token, then call real business endpoints with it."
printf '\n'
warn "Do NOT add this machine's IP to 企业可信IP first — that destroys the test."
printf '\n'
if confirm "Is 企业可信IP (Trusted Enterprise IP) still empty for this app?"; then
  say "Getting a token…"
  TOKEN_RESP=$(curl -sS --get \
    --data-urlencode "corpid=$WECOM_CORP_ID" \
    --data-urlencode "corpsecret=$WECOM_SECRET" \
    "$QYAPI/gettoken" 2>&1 || true)
  TOKEN_CODE=$(printf '%s' "$TOKEN_RESP" | jq -r '.errcode // "unparseable"' 2>/dev/null || echo unparseable)
  TOKEN=$(printf '%s' "$TOKEN_RESP" | jq -r '.access_token // empty' 2>/dev/null || true)
  note "(access_token deliberately not printed or recorded)"
  record "### 9. 企业可信IP / business-API access"
  record_kv "Called from" "an ordinary machine, IP NOT in 企业可信IP"
  record ""
  record "| Endpoint | errcode |"
  record "|---|---|"
  record "| \`/cgi-bin/gettoken\` | \`$TOKEN_CODE\` |"
  printf '\n'
  say "gettoken → errcode $TOKEN_CODE"
  BIZ_CODE="no-token"
  if [[ -n "$TOKEN" ]]; then
    for _ep in department/list user/simplelist; do
      _br=$(curl -sS --get --data-urlencode "access_token=$TOKEN" \
              --data-urlencode "department_id=1" "$QYAPI/$_ep" 2>&1 || true)
      _bc=$(printf '%s' "$_br" | jq -r '.errcode // "unparseable"' 2>/dev/null || echo unparseable)
      say "$_ep → errcode $_bc"
      record "| \`/cgi-bin/$_ep\` | \`$_bc\` |"
      [[ "$BIZ_CODE" == "no-token" ]] && BIZ_CODE="$_bc"
    done
  fi
  record ""
  printf '\n'
  case "$BIZ_CODE" in
    60020) warn "Confirmed: every WeCom business API needs a stable, enterprise-attributable"
           warn "egress IP. This DISQUALIFIES Vercel serverless for WeCom-facing code."
           warn "The proportionate fix is a ~\$5/mo fixed-IP VM as a thin API proxy —"
           warn "NOT Vercel Static IPs at \$100/mo. The group robot webhook is EXEMPT,"
           warn "so 'robot only' removes this cost entirely — a real scope cut for 11."
           record "**Reading:** whitelist enforced. \`gettoken\` is exempt and misleadingly returns 0; business APIs return 60020. Vercel serverless is disqualified for WeCom-facing code — use a ~\$5/mo fixed-IP VM as a thin proxy, not Vercel Static IPs (\$100/mo). The robot webhook is exempt." ;;
    0)     warn "Business APIs succeeded without whitelisting. That contradicts the"
           warn "post-2022-06-20 policy — record carefully, it reopens Vercel as viable."
           record "**Reading:** business APIs succeeded WITHOUT an IP whitelist — contradicts the post-2022-06-20 policy. Reopens Vercel serverless as viable for WeCom-facing code." ;;
    *)     record "**Reading:** unexpected errcode \`$BIZ_CODE\` — investigate before ticket 12 relies on it." ;;
  esac
else
  SKIPPED+=("gettoken 60020 test — 企业可信IP was already populated")
  record "### 9. 企业可信IP / gettoken"
  record_kv "Observed" "SKIPPED — 企业可信IP already populated, test invalid"
fi
record ""
pause "Press Enter for the last stage."

# ── Stage 10 — restrictions sweep and close out ───────────────────────────
stage "Restrictions sweep — and anything contradicting buildspec_1"
say "Last thing the ticket asks for: whatever the console surfaced along the way."
printf '\n'
step "Org-verification prompts, member limits, admin-permission gates, paywalls,"
step "  anything that nagged you or refused you."
ask_block RESTRICTIONS "Restrictions the console surfaced (blank + . to skip):"
printf '\n'
step "And the question ticket 12 will ask: did anything here contradict buildspec_1?"
ask_block CONTRADICTIONS "Contradictions with buildspec_1 (blank + . to skip):"
record "### 10. Restrictions and contradictions"
record_label "Restrictions surfaced:"
record_fenced "" "$RESTRICTIONS"
record_label "Contradicts \`buildspec_1\`:"
record_fenced "" "$CONTRADICTIONS"
record ""
record "---"
record ""
record "**Handoff.** Ticket 07 reads §6 and §8 (whether WeCom login is available at all)"
record "and §9 (whether Vercel can host WeCom-facing code). Ticket 08 reads §2–§5 —"
record "if mention test A failed, reopen 08."
record ""

finish
